 1| /**
 2|  * The order desk's chart: wiring only. Every rule lives in a step.
 3|  *
 4|  *   receive-order → load-customer → start-lines
 5|  *     → price-line → more-lines ─ next-line ─┐ (back to price-line)
 6|  *                               └ lines-priced
 7|  *     → apply-coupon → loyalty-discount → net-amount
 8|  *     → [tax: find-rate → compute-tax]
 9|  *     → shipping-rule ─ free-shipping | standard-shipping
10|  *     → grand-total
11|  *     → check-stock ∥ check-credit → combine-checks
12|  *     → approval ─ hold | reject | review | approve
13|  */
14| import { flowChart } from 'footprintjs';
15| 
16| import * as applyCoupon from './steps/apply-coupon/index.mjs';
17| import * as approval from './steps/approval/index.mjs';
