41| /** Builds the order desk chart. */
42| export function buildChart() {
43|   return flowChart('Receive order', receiveOrder.run, 'receive-order', { description: receiveOrder.purpose })
44|     .addFunction('Load customer', loadCustomer.run, 'load-customer', loadCustomer.purpose)
45|     .addFunction('Start lines', startLines.run, 'start-lines', startLines.purpose)
46|     .addFunction('Price line', priceLine.run, 'price-line', priceLine.purpose)
47|     .addDeciderFunction('More lines', moreLines.run, 'more-lines', moreLines.purpose)
48|     .addFunctionBranch('next-line', 'Next line', nextLine.run, nextLine.purpose, { loopTo: 'price-line' })
49|     .addFunctionBranch('lines-priced', 'Lines priced', linesPriced.run, linesPriced.purpose)
50|     .end()
51|     .addFunction('Apply coupon', applyCoupon.run, 'apply-coupon', applyCoupon.purpose)
52|     .addFunction('Loyalty discount', loyaltyDiscount.run, 'loyalty-discount', loyaltyDiscount.purpose)
53|     .addFunction('Net amount', netAmount.run, 'net-amount', netAmount.purpose)
54|     .addSubFlowChartNext('tax', buildTaxChart(), 'Tax', { inputMapper: taxInput, outputMapper: taxOutput })
55|     .addDeciderFunction('Shipping rule', shippingRule.run, 'shipping-rule', shippingRule.purpose)
56|     .addFunctionBranch('free-shipping', 'Free shipping', freeShipping.run, freeShipping.purpose)
57|     .addFunctionBranch('standard-shipping', 'Standard shipping', standardShipping.run, standardShipping.purpose)
58|     .end()
59|     .addFunction('Grand total', grandTotal.run, 'grand-total', grandTotal.purpose)
60|     .addListOfFunction([
61|       { id: 'check-stock', name: 'Check stock', fn: checkStock.run },
62|       { id: 'check-credit', name: 'Check credit', fn: checkCredit.run },
63|     ])
64|     .addFunction('Combine checks', combineChecks.run, 'combine-checks', combineChecks.purpose)
65|     .addDeciderFunction('Approval', approval.run, 'approval', approval.purpose)
66|     .addFunctionBranch('hold', 'Hold', hold.run, hold.purpose)
67|     .addFunctionBranch('reject', 'Reject', reject.run, reject.purpose)
68|     .addFunctionBranch('review', 'Review', review.run, review.purpose)
69|     .addFunctionBranch('approve', 'Approve', approve.run, approve.purpose)
70|     .end()
71|     .build();
72| }
