 1| /**
 2|  * load-customer: looks the customer up and keeps the four facts the desk
 3|  * uses later: credit limit, order limit, what they owe today, and how many
 4|  * years they have bought from us.
 5|  *
 6|  * Example: `customerId = 'C-100'` → `customer.creditLimit = 5000`.
 7|  */
 8| import { CUSTOMERS } from '../../data/customers.mjs';
 9| 
10| export const purpose = 'Look up the customer and keep their limits, balance and years.';
11| 
12| /** @param {any} scope */
13| export function run(scope) {
14|   const found = CUSTOMERS[scope.customerId];
15|   if (!found) throw new Error(`unknown customer ${scope.customerId}`);
16|   scope.customer = {
17|     creditLimit: found.creditLimit,
18|     orderLimit: found.orderLimit,
19|     openBalance: found.openBalance,
20|     memberYears: found.memberYears,
21|   };
22| }
